CREATE TABLE IF NOT EXISTS public.species_ref(id text PRIMARY KEY,name text NOT NULL,rarity text NOT NULL,role text NOT NULL,hp int NOT NULL,atk int NOT NULL,def int NOT NULL,spd int NOT NULL);
GRANT SELECT ON public.species_ref TO authenticated, anon; GRANT ALL ON public.species_ref TO service_role;
ALTER TABLE public.species_ref ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "species_ref readable" ON public.species_ref;
CREATE POLICY "species_ref readable" ON public.species_ref FOR SELECT TO authenticated, anon USING (true);
TRUNCATE public.species_ref;
