CREATE OR REPLACE FUNCTION public._bot_species_rarity(sp text) RETURNS text LANGUAGE sql STABLE SET search_path TO 'public' AS $f$ SELECT COALESCE((SELECT rarity FROM public.species_ref WHERE id=sp),'common') $f$;
CREATE OR REPLACE FUNCTION public._bot_species_name(sp text) RETURNS text LANGUAGE sql STABLE SET search_path TO 'public' AS $f$ SELECT COALESCE((SELECT name FROM public.species_ref WHERE id=sp),'Pokemon') $f$;
CREATE OR REPLACE FUNCTION public._bot_species_role(sp text) RETURNS text LANGUAGE sql STABLE SET search_path TO 'public' AS $f$ SELECT COALESCE((SELECT role FROM public.species_ref WHERE id=sp),'dps') $f$;
CREATE OR REPLACE FUNCTION public._bot_species_stats(sp text) RETURNS TABLE(hp int,atk int,def int,spd int) LANGUAGE sql STABLE SET search_path TO 'public' AS $f$ SELECT hp,atk,def,spd FROM public.species_ref WHERE id=sp $f$;
CREATE OR REPLACE FUNCTION public._bot_random_species(rarity text) RETURNS text LANGUAGE sql STABLE SET search_path TO 'public' AS $f$ SELECT s.id FROM public.species_ref s WHERE s.rarity = CASE WHEN rarity='epic' THEN 'legendary' ELSE rarity END ORDER BY random() LIMIT 1 $f$;

