UPDATE public.monsters m
SET species = pick.id, name = pick.name
FROM old_sp, LATERAL (SELECT s.id, s.name FROM public.species_ref s WHERE s.rarity = old_sp.orar ORDER BY random() LIMIT 1) pick
WHERE m.species = old_sp.oid;